import pathlib,hashlib,tarfile,json
p=pathlib.Path('/tmp/mad-packet')
assert p.stat().st_size==9487608 and hashlib.sha256(p.read_bytes()).hexdigest()=='e77cb5b768c4b07026250d815f264c590dcde12c4426500d1522bba84ece19d1'
r=pathlib.Path('/home/user/madbomber-runtime');r.mkdir(exist_ok=True)
with tarfile.open(p) as t:
 for m in t.getmembers():
  assert not m.issym() and not m.islnk() and not pathlib.PurePosixPath(m.name).is_absolute() and '..' not in pathlib.PurePosixPath(m.name).parts
 t.extractall(r)
print(json.dumps({'transferVerified':True,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'root':str(r)}))

import base64
s=base64.b64decode('');(r/'reset-runtime.py').write_bytes(s);print(hashlib.sha256(s).hexdigest())
